import pandas as pd
import numpy as np

# Load the data
no2_data = pd.read_csv('chunks_csv/getisord/getisord_2022_no2.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
no2_data = no2_data.dropna()

# Calculate the total NO2 for each local area
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhoods:
        neighborhoods[borough] = []
    neighborhoods[borough].append(neighbor)
    if neighbor not in neighborhoods:
        neighborhoods[neighbor] = []
    neighborhoods[neighbor].append(borough)

total_no2 = {}
for borough, neighbors in neighborhoods.items():
    total_no2[borough] = no2_data.loc[no2_data['borough'].isin(neighbors), 'NO2_value'].sum()

# Calculate the citywide average NO2
citywide_average = no2_data['NO2_value'].mean()

# Calculate the standard deviation of NO2 for all boroughs
std_dev = no2_data['NO2_value'].std()

# Calculate the z-score for each local area
z_scores = {}
for borough, total in total_no2.items():
    z_scores[borough] = (total - citywide_average) / std_dev

# Identify hot and cold spots
hot_spots = {borough: z_score for borough, z_score in z_scores.items() if np.abs(z_score) > 1.96}
cold_spots = {borough: z_score for borough, z_score in z_scores.items() if np.abs(z_score) > 1.96 and z_score < 0}

# Store the results
results = []
for borough, z_score in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z_score}, gi_value={z_score})")
for borough, z_score in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z_score}, gi_value={z_score})")

# Print the results
print(f"data_points_used = {len(no2_data)}")
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
